const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// Security middleware
app.use(helmet());

// Rate limiting configuration
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
    retryAfter: '15 minutes'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for sensitive endpoints (if you add auth endpoints)
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts per 15 minutes
  skipSuccessfulRequests: true,
});

// Body parser with size limits to prevent DoS
app.use(express.json({ 
  limit: '1mb', // Limit request body size
  strict: true // Only accept objects and arrays
}));
app.use(express.urlencoded({ 
  extended: false, 
  limit: '1mb' 
}));

// Request timeout middleware
app.use((req, res, next) => {
  res.setTimeout(30000, () => {
    res.status(408).json({ 
      error: 'Request timeout',
      code: 'REQUEST_TIMEOUT'
    });
  });
  next();
});

// Validation middleware helper
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

// Sanitize user data before sending response
const sanitizeUser = (user) => ({
  id: user.id,
  name: user.name,
  email: user.email
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Users endpoint with input validation
app.get('/users', [
  // Validate query parameters
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer')
    .toInt(),
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer')
    .toInt()
], validateRequest, (req, res) => {
  try {
    const { limit, offset, id } = req.query;

    // Sample user data (in production, this would come from a database)
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    let users = allUsers;

    // Filter by ID if provided
    if (id) {
      users = users.filter(user => user.id === id);
    }

    // Apply pagination
    const start = offset || 0;
    const end = limit ? start + limit : users.length;
    users = users.slice(start, end);

    // Sanitize and return users
    const sanitizedUsers = users.map(sanitizeUser);

    res.json({
      data: sanitizedUsers,
      count: sanitizedUsers.length,
      pagination: {
        limit: limit || users.length,
        offset: start
      }
    });

  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({
      error: 'Internal server error',
      code: 'INTERNAL_ERROR'
    });
  }
});

// Example of creating a user with validation
app.post('/users', [
  body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ min: 2, max: 100 })
    .withMessage('Name must be between 2 and 100 characters')
    .escape(), // Escape HTML entities to prevent XSS
  body('email')
    .trim()
    .notEmpty()
    .withMessage('Email is required')
