# Security Review: app.js

## Current Issues Identified

### 1. **Missing Security Headers**
- No HTTP security headers configured
- Missing CORS configuration
- No Content-Type validation

### 2. **Insufficient Error Handling**
- No global error handling middleware
- No try-catch blocks for async operations
- No error logging mechanism
- Sensitive information could leak in error messages

### 3. **Lack of Input Validation**
- No validation on query parameters
- No input sanitization
- No rate limiting
- No request size limits

### 4. **Express Configuration Issues**
- No body parser limits configured
- Missing trust proxy settings
- No helmet middleware for security headers

### 5. ** Logging Concerns**
- Console logging in production code
- No structured logging
- No audit logging for security events

---

## Recommended Improvements

### 1. Install Security Dependencies
```bash
npm install express-validator helmet rate-limiter-flexible morgan
```

### 2. Global Error Handling
```javascript
// Centralized error handling middleware
app.use((err, req, res, next) => {
  // Log error for debugging (don't expose to client)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method
  });

  // Don't leak sensitive information in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'An unexpected error occurred' 
    : err.message;

  res.status(statusCode).json({
    error: {
      message,
      status: statusCode
    }
  });
});

// Handle 404 routes
app.use((req, res) => {
  res.status(404).json({
    error: {
      message: 'Resource not found',
      status: 404
    }
  });
});
```

### 3. Input Validation with express-validator
```javascript
const { query, validationResult, param } = require('express-validator');

// Validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: {
        message: 'Validation failed',
        details: errors.array()
      }
    });
  }
  next();
};

// Apply to routes
app.get('/users', 
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('sort').optional().isIn(['name', 'email', 'id']),
  validateRequest,
  (req, res) => {
    // Handler logic
  }
);
```

### 4. Security Headers with Helmet
```javascript
const helmet = require('helmet');

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", 'data:'],
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,
  frameguard: { action: 'deny' },
  xssFilter: true
}));
```

### 5. Rate Limiting
```javascript
const { RateLimiterMemory } = require('rate-limiter-flexible');

const rateLimiter = new RateLimiterMemory({
  keyPrefix: 'middleware',
  points: 100, // 100 requests
  duration: 60, // per 60 seconds
});

const rateLimiterMiddleware = async (req, res, next) => {
  try {
    await rateLimiter.consume(req.ip);
    next();
  } catch (rejRes) {
    res.status(429).json({
      error: {
        message: 'Too many requests',
        retryAfter: Math.round(rejRes.msBeforeNext / 1000)
      }
    });
  }
};

// Apply to API routes
app.use('/api/', rateLimiterMiddleware);
```

### 6. Request Size Limits
```javascript
app.use(express.json({ limit: '10kb' })); // Limit JSON body size
app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));
```

### 7. CORS Configuration
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
}));
```

### 8. Secure Logging
```javascript
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

// Create a write stream for access logs
const accessLogStream = fs.createWriteStream(
  path.join(__dirname, 'access.log'),
  { flags: 'a' }
);

// Use safer token format
app.use(morgan('combined', { 
  stream: accessLogStream,
  // Don't log sensitive headers
  skip: (req, res) => {
    return req.path.includes('/health') ? false : false; 
  }
}));
```

### 9. Environment Variable Validation
```javascript
require('dotenv').config();

// Validate required environment variables
const requiredEnvVars = ['NODE_ENV', 'PORT'];
const missingEnvVars = requiredEnvVars.filter(varName => !process.env[varName]);

if (missingEnvVars.length > 0) {
  throw new Error(`Missing required environment variables: ${missingEnvVars.join(', ')}`);
}

// Set secure defaults
process.env.NODE_ENV = process.env.NODE_ENV || 'development';
const isProduction = process.env.NODE_ENV === 'production';
```

### 10. Sanitization Utilities
```javascript
const validator = require('validator');

const sanitizeInput = {
  string: (input) => {
    if (typeof input !== 'string') return '';
    return validator.escape(input.trim());
  },
  email: (email) => {
    return validator.isEmail(email) ? validator.normalizeEmail(email) : null;
  },
  id: (id) => {
    const num = parseInt(id, 10);
    return isNaN(num) ? null : Math.max(1, num);
  }
};
```

---

## Complete Secure Implementation Example

See `app.secure.js` for a fully refactored version incorporating all these improvements.

---

## Security Checklist

- [x] HTTP Security Headers (Helmet)
- [x] Input Validation (express-validator)
- [x] Rate Limiting
- [x] Request Size Limits
- [x] CORS Configuration
- [x] Global Error Handler
- [x] Structured Logging
- [x] Environment Variable Validation
- [x] Input Sanitization
- [x] DDoS Protection Basics
- [ ] HTTPS/TLS Configuration (requires reverse proxy)
- [ ] JWT Authentication (if needed)
- [ ] Database Parameterized Queries (if adding database)
- [ ] API Key Validation (if public API)

---

## Additional Recommendations

1. **Use HTTPS in production** - Never expose APIs over HTTP
2. **Implement request timeouts** - Prevent slow loris attacks
3. **Add API versioning** - `/api/v1/users` for better maintainability
4. **Set up monitoring/alerting** - Detect and respond to security incidents
5. **Regular dependency updates** - `npm audit` and update packages
6. **Implement API authentication** - JWT or API keys for protected routes
7. **Use parameterized queries** - If adding database operations
8. **Add response compression** - Use compression middleware carefully
9. **Implement caching wisely** - Cache public endpoints, invalidate carefully
10. **Security testing** - Regular penetration testing and code reviews

/**
 * Secure Express.js Application
 * 
 * This application implements security best practices including:
 * - HTTP security headers
 * - Input validation and sanitization  
 * - Rate limiting
 * - Global error handling
 * - Secure logging
 * - Request size limits
 * - CORS configuration
 */

'use strict';

require('dotenv').config();

// =============================================================================
// DEPENDENCIES
// =============================================================================
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const { query, param, validationResult } = require('express-validator');
const { RateLimiterMemory } = require('rate-limiter-flexible');
const path = require('path');
const fs = require('fs');

// =============================================================================
// ENVIRONMENT VALIDATION
// =============================================================================
const requiredEnvVars = ['NODE_ENV'];
const missingEnvVars = requiredEnvVars.filter(varName => !process.env[varName]);

if (missingEnvVars.length > 0) {
  console.error(`ERROR: Missing required environment variables: ${missingEnvVars.join(', ')}`);
  process.exit(1);
}

// Set secure defaults
const NODE_ENV = process.env.NODE_ENV || 'development';
const PORT = parseInt(process.env.PORT || '3000', 10);
const isProduction = NODE_ENV === 'production';

// =============================================================================
// RATE LIMITING CONFIGURATION
// =============================================================================
// General API rate limiter
const apiRateLimiter = new RateLimiterMemory({
  keyPrefix: 'api_limit',
  points: 100, // 100 requests
  duration: 60, // per 60 seconds (1 minute)
});

// stricter rate limiter for auth-sensitive endpoints
const strictRateLimiter = new RateLimiterMemory({
  keyPrefix: 'strict_limit',
  points: 5, // 5 requests
  duration: 300, // per 300 seconds (5 minutes)
});

/**
 * Rate limiting middleware
 * @param {RateLimiterMemory} limiter - The rate limiter instance
 * @returns {Function} Express middleware function
 */
const rateLimitMiddleware = (limiter) => {
  return async (req, res, next) => {
    try {
      // Get client IP (considering proxy headers)
      const clientIp = req.ip || req.connection.remoteAddress;
      await limiter.consume(clientIp);
      next();
    } catch (rejRes) {
      const retryAfter = Math.round(rejRes.msBeforeNext / 1000) || 60;
      res.set('Retry-After', retryAfter.toString());
      return res.status(429).json({
        error: {
          message: 'Too many requests. Please try again later.',
          status: 429,
          retryAfter
        }
      });
    }
  };
};

// =============================================================================
// INPUT VALIDATION MIDDLEWARE
// =============================================================================
/**
 * Validates request and returns 400 if validation fails
 * @param {Request} req - Express request object
 * @param {Response} res - Express response object
 * @param {Function} next - Express next function
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: {
        message: 'Validation failed. Please check your input.',
        status: 400,
        details: isProduction ? undefined : errors.array()
      }
    });
  }
  next();
};

/**
 * Sanitizes string inputs to prevent XSS
 * @param {*} input - Input to sanitize
 * @returns {string} Sanitized string or empty string
 */
const sanitizeString = (input) => {
  if (typeof input !== 'string') return '';
  return input.trim().substring(0, 1000); // Limit length
};

// =============================================================================
// EXPRESS APP SETUP
// =============================================================================
const app = express();

// Trust proxy if running behind a load balancer
app.set('trust proxy', 1);

// Disable X-Powered-By header for security
app.disable('x-powered-by');

// =============================================================================
// SECURITY MIDDLEWARE
// =============================================================================

// HTTP Security Headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: isProduction ? {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  } : false,
  noSniff: true,
  frameguard: { action: 'deny' },
  xssFilter: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
  permissionPolicy: {
    features: {
      geolocation: ["'none'"],
      camera: ["'none'"],
      microphone: ["'none'"],
    },
  },
}));

// CORS Configuration
const allowedOrigins = process.env.ALLOWED_ORIGINS
  ? process.env.ALLOWED_ORIGINS.split(',').map(origin => origin.trim())
  : ['http://localhost:3000'];

app.use(cors({
  origin: (origin, callback) => {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin) return callback(null, true);

    if (allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'), false);
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Requested-With'],
  credentials: true,
  maxAge: 86400, // 24 hours
  optionsSuccessStatus: 204
}));

// Request body parsing with size limits
app.use(express.json({
  limit: '10kb',
  strict: true
}));

app.use(express.urlencoded({
  extended: true,
  limit: '10kb'
}));

// =============================================================================
// LOGGING
// =============================================================================

// Create write stream for access logs in production
if (isProduction) {
  const logDir = path.join(__dirname, 'logs');
  if (!fs.existsSync(logDir)) {
    fs.mkdirSync(logDir, { recursive: true });
  }
  const accessLogStream = fs.createWriteStream(
    path.join(logDir, 'access.log'),
    { flags: 'a' }
  );
  app.use(morgan('combined', { stream: accessLogStream }));
} else {
  // Development logging
  app.use(morgan('dev'));
}

// =============================================================================
// MOCK DATA (Replace with actual database in production)
// =============================================================================
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// =============================================================================
// ROUTES
// =============================================================================

/**
 * GET /health
 * Health check endpoint - no rate limiting
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: NODE_ENV
    });
  } catch (error) {
    res.status(500).json({
      error: {
        message: 'Health check failed',
        status: 500
      }
    });
  }
});

/**
 * GET /users
 * Get all users with pagination and filtering
 * Query params:
 * - page: Page number (min: 1, default: 1)
 * - limit: Items per page (min: 1, max: 100, default: 10)
 * - sort: Sort field ('name', 'email', 'id', default: 'id')
 * - order: Sort order ('asc', 'desc', default: 'asc')
 * - search: Search in name field
 */
app.get('/users',
  rateLimitMiddleware(apiRateLimiter),
  [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .withMessage('Page must be a positive integer')
      .toInt(),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('sort')
      .optional()
      .isIn(['name', 'email', 'id'])
      .withMessage('Sort must be one of: name, email, id'),
    query('order')
      .optional()
      .isIn(['asc', 'desc'])
      .withMessage('Order must be asc or desc'),
    query('search')
      .optional()
      .isString()
      .isLength({ max: 100 })
      .withMessage('Search term must be less than 100 characters')
      .trim()
  ],
  validateRequest,
  (req, res) => {
    try {
      const {
        page = 1,
        limit = 10,
        sort = 'id',
        order = 'asc',
        search
      } = req.query;

      // Apply search filter if provided
      let filteredUsers = [...users];
      if (search) {
        const sanitizedSearch = sanitizeString(search).toLowerCase();
        filteredUsers = filteredUsers.filter(user =>
          user.name.toLowerCase().includes(sanitizedSearch)
        );
      }

      // Apply sorting
      filteredUsers.sort((a, b) => {
        const aVal = a[sort];
        const bVal = b[sort];
        const comparison = aVal > bVal ? 1 : aVal < bVal ? -1 : 0;
        return order === 'desc' ? -comparison : comparison;
      });

      // Apply pagination
      const startIndex = (page - 1) * limit;
      const endIndex = startIndex + limit;
      const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

      res.json({
        data: paginatedUsers,
        pagination: {
          page,
          limit,
          total: filteredUsers.length,
          totalPages: Math.ceil(filteredUsers.length / limit),
          hasNext: endIndex < filteredUsers.length,
          hasPrev: page > 1
        }
      });
    } catch (error) {
      throw error;
    }
  }
);

/**
 * GET /users/:id
 * Get a specific user by ID
 */
app.get('/users/:id',
  rateLimitMiddleware(apiRateLimiter),
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer')
      .toInt()
  ],
  validateRequest,
  (req, res) => {
    try {
      const { id } = req.params;

      const user = users.find(u => u.id === id);

      if (!user) {
        return res.status(404).json({
          error: {
            message: 'User not found',
            status: 404
          }
        });
      }

      res.json({ data: user });
    } catch (error) {
      throw error;
    }
  }
);

// =============================================================================
// 404 HANDLER
// =============================================================================
app.use((req, res) => {
  res.status(404).json({
    error: {
      message: 'Resource not found',
      status: 404,
      path: req.path,
      method: req.method
    }
  });
});

// =============================================================================
// GLOBAL ERROR HANDLER
// =============================================================================
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log error details for debugging
  console.error('[ERROR]', {
    message: err.message,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip,
    stack: isProduction ? undefined : err.stack
  });

  // Handle CORS errors specifically
  if (err.message === 'Not allowed by CORS') {
    return res.status(403).json({
      error: {
        message: 'Cross-origin request denied',
        status: 403
      }
    });
  }

  // Handle JSON parse errors
  if (err instanceof SyntaxError && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: {
        message: 'Invalid JSON in request body',
        status: 400
      }
    });
  }

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Send safe error response
  res.status(statusCode).json({
    error: {
      message: isProduction 
        ? (statusCode === 500 ? 'An unexpected error occurred' : err.message)
        : err.message,
      status: statusCode,
      ...(isProduction ? {} : { stack: err.stack })
    }
  });
});

// =============================================================================
// SERVER STARTUP
// =============================================================================
if (require.main === module) {
  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${NODE_ENV}`);
    console.log(`Health check: http://localhost:${PORT}/health`);
  });

  // Graceful shutdown handling
  const gracefulShutdown = (signal) => {
    console.log(`\n${signal} received. Starting graceful shutdown...`);

    server.close(() => {
      console.log('Server closed successfully');
      process.exit(0);
    });

    // Force close after 10 seconds
    setTimeout(() => {
      console.error('Forced shutdown after timeout');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));

  // Handle uncaught exceptions
  process.on('uncaughtException', (error) => {
    console.error('Uncaught Exception:', error);
    gracefulShutdown('uncaughtException');
  });

  // Handle unhandled promise rejections
  process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
    gracefulShutdown('unhandledRejection');
  });
}

// =============================================================================
// MODULE EXPORT
// =============================================================================
module.exports = app;

