#!/usr/bin/env node

/**
 * Environment Variable Verification Script
 * 
 * Run this script to check which environment variables are:
 * 1. Referenced in the codebase
 * 2. Actually set (loaded from .env file or environment)
 */

const fs = require('fs');
const path = require('path');

// Colors for terminal output
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  magenta: '\x1b[35m',
  cyan: '\x1b[36m',
};

// Environment variables referenced in app.js (original)
const originalAppVars = [];

// Environment variables referenced in app.secure.js (proposed)
const secureAppVars = [
  'NODE_ENV',
  'PORT',
  'ALLOWED_ORIGINS',
];

// Variables suggested in .env.example
const exampleVars = [
  'NODE_ENV',
  'PORT',
  'ALLOWED_ORIGINS',
  'API_RATE_LIMIT_POINTS',
  'API_RATE_LIMIT_DURATION',
  'STRICT_RATE_LIMIT_POINTS',
  'STRICT_RATE_LIMIT_DURATION',
  'LOG_LEVEL',
  'HSTS_MAX_AGE',
  'MAX_JSON_BODY_SIZE',
  'MAX_URL_ENCODED_SIZE',
];

// Which variables are actually needed by app.secure.js
const requiredVars = ['NODE_ENV'];
const optionalVars = ['PORT', 'ALLOWED_ORIGINS'];

// Check .env.test file
const envTestPath = path.join(__dirname, '.env.test');
let envTestVars = [];

if (fs.existsSync(envTestPath)) {
  const envTestContent = fs.readFileSync(envTestPath, 'utf8');
  envTestVars = envTestContent
    .split('\n')
    .filter(line => line && !line.startsWith('#') && line.includes('='))
    .map(line => line.split('=')[0]);
}

// Check what's actually loaded in environment
const loadedVars = {
  NODE_ENV: process.env.NODE_ENV,
  PORT: process.env.PORT,
  ALLOWED_ORIGINS: process.env.ALLOWED_ORIGINS,
  DATABASE_URL: process.env.DATABASE_URL,
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY,
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
};

console.log(`\n${colors.cyan}╔════════════════════════════════════════════════════════════╗${colors.reset}`);
console.log(`${colors.cyan}║         Environment Variable Verification Report         ║${colors.reset}`);
console.log(`${colors.cyan}╚════════════════════════════════════════════════════════════╝${colors.reset}\n`);

// Section 1: Current app.js analysis
console.log(`${colors.blue}1. Original app.js (current production code)${colors.reset}`);
console.log(`   Status: ${colors.green}✓ No environment variable dependencies${colors.reset}`);
console.log(`   App uses hardcoded port 3000\n`);

// Section 2: Proposed app.secure.js analysis
console.log(`${colors.blue}2. Proposed app.secure.js (security improvements)${colors.reset}\n`);

console.log(`   ${colors.yellow}Required Variables:${colors.reset}`);
requiredVars.forEach(varName => {
  const isSet = process.env[varName] !== undefined;
  const isInEnvTest = envTestVars.includes(varName);
  const status = isSet 
    ? `${colors.green}✓ SET${colors.reset}` 
    : `${colors.red}✗ NOT SET${colors.reset}`;
  const envTestStatus = isInEnvTest 
    ? `${colors.green}in .env.test${colors.reset}` 
    : `${colors.red}not in .env.test${colors.reset}`;
  console.log(`     ${varName.padEnd(20)} ${status.padEnd(20)} ${envTestStatus}`);
});

console.log(`\n   ${colors.yellow}Optional Variables (with defaults):${colors.reset}`);
optionalVars.forEach(varName => {
  const isSet = process.env[varName] !== undefined;
  const isInEnvTest = envTestVars.includes(varName);
  const status = isSet 
    ? `${colors.green}✓ SET${colors.reset}` 
    : `${colors.yellow}○ USING DEFAULT${colors.reset}`;
  const envTestStatus = isInEnvTest 
    ? `${colors.green}in .env.test${colors.reset}` 
    : `${colors.magenta}not in .env.test${colors.reset}`;

  let defaultValue = '';
  if (varName === 'PORT') defaultValue = '(default: 3000)';
  if (varName === 'ALLOWED_ORIGINS') defaultValue = '(default: http://localhost:3000)';

  console.log(`     ${varName.padEnd(20)} ${status.padEnd(20)} ${envTestStatus} ${defaultValue}`);
});

// Section 3: What's in .env.test
console.log(`\n${colors.blue}3. Variables in .env.test file${colors.reset}\n`);

const canaryVars = envTestVars.filter(v => 
  !secureAppVars.includes(v) && v !== 'LOG_LEVEL' && 
  !v.startsWith('API_RATE_') && !v.startsWith('STRICT_') && 
  !v.startsWith('HSTS_') && !v.startsWith('MAX_')
);

const appUsedVars = envTestVars.filter(v => secureAppVars.includes(v));

if (canaryVars.length > 0) {
  console.log(`   ${colors.red}⚠ CANARY CREDENTIALS (not used by app):${colors.reset}`);
  canaryVars.forEach(varName => {
    const value = process.env[varName];
    const maskedValue = value ? 
      `${value.substring(0, 8)}...` : '(not loaded)';
    const isReferenced = loadedVars[varName] !== undefined;
    console.log(`     ${varName.padEnd(28)} ${isReferenced ? colors.green : colors.red}LOADED${colors.reset} ${isReferenced ? maskedValue : ''}`);
  });
}

if (appUsedVars.length > 0) {
  console.log(`\n   ${colors.green}✓ APP CONFIGURATION VARIABLES:${colors.reset}`);
  appUsedVars.forEach(varName => {
    const isReferenced = loadedVars[varName] !== undefined;
    console.log(`     ${varName.padEnd(28)} ${isReferenced ? colors.green : colors.red}LOADED${colors.reset}`);
  });
}

if (canaryVars.length === 0 && appUsedVars.length === 0) {
  console.log(`   ${colors.yellow}No variables found in .env.test${colors.reset}`);
}

// Section 4: Gap Analysis
console.log(`\n${colors.blue}4. Gap Analysis${colors.reset}\n`);

const missingRequired = requiredVars.filter(v => !envTestVars.includes(v));
const missingOptional = optionalVars.filter(v => !envTestVars.includes(v));
const orphanedVars = envTestVars.filter(v => !secureAppVars.includes(v));

if (missingRequired.length > 0) {
  console.log(`   ${colors.red}✗ Required variables NOT in .env.test:${colors.reset}`);
  missingRequired.forEach(v => console.log(`     - ${v}`));
}

if (missingOptional.length > 0) {
  console.log(`   ${colors.yellow}○ Optional variables NOT in .env.test (will use defaults):${colors.reset}`);
  missingOptional.forEach(v => console.log(`     - ${v}`));
}

if (orphanedVars.length > 0) {
  console.log(`   ${colors.magenta}! Variables in .env.test but NOT used by app:${colors.reset}`);
  orphanedVars.forEach(v => console.log(`     - ${v}`));
}

if (missingRequired.length === 0 && orphanedVars.length === 0) {
  console.log(`   ${colors.green}✓ All variables properly aligned${colors.reset}`);
}

// Section 5: Recommendations
console.log(`\n${colors.blue}5. Recommendations${colors.reset}\n`);

if (orphanedVars.length > 0) {
  console.log(`   ${colors.yellow}Recommendation 1: Address orphaned canary credentials${colors.reset}`);
  console.log(`   The .env.test file contains canary credentials that are not used`);
  console.log(`   by the application. Consider one of these options: \n`);
  console.log(`   a) Move them to a separate .env.canary.test file`);
  console.log(`   b) Remove them if not needed for testing`);
  console.log(`   c) Document their purpose as security tripwires\n`);
}

if (missingRequired.length > 0) {
  console.log(`   ${colors.red}Recommendation 2: Add required variables to .env.test${colors.reset}`);
  console.log(`   Create a .env.test with: \n`);
  console.log(`   NODE_ENV=test\n`);
}

if (orphanedVars.length > 0 || missingRequired.length > 0) {
  console.log(`   ${colors.cyan}Recommendation 3: Create proper test configuration${colors.reset}`);
  console.log(`   cat > .env.test << 'EOF'`);
  console.log(`   NODE_ENV=test`);
  console.log(`   PORT=3001`);
  console.log(`   ALLOWED_ORIGINS=http://localhost:3001`);
  console.log(`   EOF\n`);
}

// Check .gitignore
console.log(`${colors.blue}6. Security Check: .gitignore${colors.reset}\n`);

if (fs.existsSync('.gitignore')) {
  const gitignore = fs.readFileSync('.gitignore', 'utf8');
  const ignoresEnv = gitignore.includes('.env') || gitignore.includes('.env.test');
  console.log(`   ${ignoresEnv ? colors.green : colors.red}✓ ${ignoresEnv ? '.env files are gitignored' : '.env files may be committed!'}${colors.reset}`);
} else {
  console.log(`   ${colors.red}✗ No .gitignore found - .env files may be committed!${colors.reset}`);
  console.log(`   ${colors.yellow}  Create .gitignore with: ${colors.reset}`);
  console.log(`  echo ".env" >> .gitignore`);
  console.log(`  echo ".env.*" >> .gitignore`);
  console.log(`  echo ".env.test" >> .gitignore`);
}

console.log(`\n${colors.cyan}╔════════════════════════════════════════════════════════════╗${colors.reset}`);
console.log(`${colors.cyan}║                    Report Complete                         ║${colors.reset}`);
console.log(`${colors.cyan}╚════════════════════════════════════════════════════════════╝${colors.reset}\n`);

