// Improved Express application with security best practices
// Error handling, input validation, and security middleware

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Use Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for user endpoints
const userLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 30, // stricter limit for user data
  message: {
    error: 'Too many user requests, please try again later.',
  },
});

// Body size limits to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Middleware to check validation results
 * Returns 400 with validation errors if any exist
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
      })),
    });
  }
  next();
};

/**
 * Sanitize user input by removing potentially dangerous characters
 */
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;
  // Remove potentially dangerous characters
  return input
    .replace(/[<>]/g, '') // Remove < and > to prevent XSS
    .trim();
};

// ============================================================================
// ERROR HANDLING
// ============================================================================

/**
 * Custom error class for application-specific errors
 */
class AppError extends Error {
  constructor(message, statusCode = 500, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.name = 'AppError';
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * 404 Not Found handler
 */
app.use((req, res, next) => {
  next(new AppError(`Route ${req.originalUrl} not found`, 404));
});

/**
 * Global error handling middleware
 * Handles all errors and prevents stack trace leakage in production
 */
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    statusCode: err.statusCode,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip,
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Prepare error response
  const errorResponse = {
    error: err.message || 'Internal Server Error',
    statusCode,
    timestamp: new Date().toISOString(),
  };

  // Include stack trace only in development
  if (process.env.NODE_ENV === 'development') {
    errorResponse.stack = err.stack;
  }

  // Send error response
  res.status(statusCode).json(errorResponse);
});

// ============================================================================
// ASYNC WRAPPER FOR ERROR HANDLING
// ============================================================================

/**
 * Wrapper to catch errors in async route handlers
 * @param {Function} fn - Async route handler function
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * GET /health - Health check endpoint
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    next(new AppError('Health check failed', 503));
  }
});

/**
 * GET /users - Get users with optional filtering
 * Query params:
 *   - id: Filter by user ID (must be positive integer)
 *   - limit: Limit number of results (1-100, default 10)
 *   - offset: Offset for pagination (default 0)
 */
app.get(
  '/users',
  userLimiter,
  [
    // Validate query parameters
    query('id')
      .optional()
      .isInt({ min: 1 })
      .withMessage('ID must be a positive integer')
      .toInt(),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const { id, limit = 10, offset = 0 } = req.query;

    // Mock database of users
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'admin' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'user' },
    ];

    // Filter by ID if provided
    let result = users;
    if (id) {
      result = users.filter(user => user.id === id);
      if (result.length === 0) {
        throw new AppError('User not found', 404);
      }
    }

    // Apply pagination
    const paginatedResult = result.slice(offset, offset + limit);

    // Remove sensitive data (in real app, use proper data filtering)
    const safeResult = paginatedResult.map(({ password, ...user }) => user);

    res.json({
      data: safeResult,
      meta: {
        count: safeResult.length,
        total: result.length,
        limit,
        offset,
      },
    });
  })
);

/**
 * POST /users - Create a new user
 * Body:
 *   - name: User name (2-50 chars)
 *   - email: Valid email address
 *   - password: Password (min 8 chars)
 */
app.post(
  '/users',
  userLimiter,
  [
    // Validate request body
    body('name')
      .trim()
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .isEmail()
      .normalizeEmail()
      .withMessage('Invalid email address'),
    body('password')
      .isLength({ min: 8 })
      .withMessage('Password must be at least 8 characters')
      .matches(/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/)
      .withMessage('Password must contain uppercase, lowercase, and number'),
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const { name, email, password } = req.body;

    // Sanitize input
    const sanitizedName = sanitizeInput(name);
    const sanitizedEmail = sanitizeInput(email);

    // In a real app, check for duplicate email, hash password, etc.
    // const hashedPassword = await bcrypt.hash(password, 10);

    // Simulate user creation
    const newUser = {
      id: Date.now(), // In real app, use proper ID generation
      name: sanitizedName,
      email: sanitizedEmail,
      createdAt: new Date().toISOString(),
    };

    // Return 201 Created with location header
    res.status(201).json({
      message: 'User created successfully',
      data: newUser,
    });
  })
);

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// ============================================================================
// GRACEFUL SHUTDOWN
// ============================================================================

/**
 * Graceful shutdown handler
 */
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force close after 10 seconds
  setTimeout(() => {
    console.error('Forcing server close after timeout');
    process.exit(1);
  }, 10000);
};

// Handle shutdown signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  gracefulShutdown('uncaughtException');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  gracefulShutdown('unhandledRejection');
});

module.exports = app;

