const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ===== SECURITY MIDDLEWARE =====

// Security headers
app.use(helmet({
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", 'data:'],
    }
  }
}));

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter limit for sensitive endpoints
  message: 'Rate limit exceeded for this endpoint',
});

app.use(limiter);

// Request body size limit to prevent DoS via large payloads
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// CORS configuration (restrict to allowed origins)
app.use((req, res, next) => {
  const allowedOrigins = (process.env.ALLOWED_ORIGINS || '').split(',').filter(Boolean);
  const origin = req.headers.origin;

  if (allowedOrigins.length > 0 && origin && allowedOrigins.includes(origin)) {
    res.setHeader('Access-Control-Allow-Origin', origin);
  }

  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');
  res.setHeader('Access-Control-Allow-Credentials', 'true');

  if (req.method === 'OPTIONS') {
    return res.sendStatus(204);
  }
  next();
});

// ===== INPUT VALIDATION MIDDLEWARE =====

/**
 * Validation middleware - checks for validation errors
 * Returns 400 Bad Request if validation fails
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation failures for security monitoring
    console.warn(`Validation failed: ${JSON.stringify(errors.array())}`, {
      ip: req.ip,
      path: req.path,
      userAgent: req.get('user-agent')
    });

    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

/**
 * Sanitization middleware to prevent injection attacks
 */
const sanitizeInput = (req, res, next) => {
  // Sanitize query parameters
  for (const key in req.query) {
    if (typeof req.query[key] === 'string') {
      req.query[key] = req.query[key]
        .trim()
        .replace(/[<>]/g, '') // Basic XSS prevention
        .substring(0, 1000); // Limit input length
    }
  }

  // Sanitize params
  for (const key in req.params) {
    if (typeof req.params[key] === 'string') {
      req.params[key] = req.params[key]
        .trim()
        .replace(/[<>]/g, '')
        .substring(0, 100);
    }
  }

  next();
};

app.use(sanitizeInput);

// ===== ERROR HANDLING MIDDLEWARE =====

/**
 * 404 handler for undefined routes
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found',
    path: req.path
  });
});

/**
 * Global error handler
 * Catches all unhandled errors and prevents information leakage
 */
app.use((err, req, res, next) => {
  // Log error details for debugging (use proper logging library in production)
  console.error('Error occurred:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    ip: req.ip,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Send safe error response (don't leak internal details)
  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'development' ? err.message : 'Internal Server Error',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ===== HEALTH CHECK (with optional authentication) =====

app.get('/health', strictLimiter, (req, res) => {
  // Optional: Add authentication token check
  const healthToken = req.headers['x-health-token'];
  if (process.env.HEALTH_CHECK_TOKEN && healthToken !== process.env.HEALTH_CHECK_TOKEN) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// ===== ROUTES =====

/**
 * GET /users
 * Returns a list of users with pagination support
 * Validations: limit and offset must be positive integers
 */
app.get('/users', 
  strictLimiter,
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('fields')
      .optional()
      .matches(/^[a-zA-Z,_]+$/)
      .withMessage('Fields must contain only letters, commas, and underscores')
  ],
  validateRequest,
  (req, res) => {
    try {
      const { limit = 10, offset = 0, fields } = req.query;

      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      ];

      // Filter fields if specified (prevents over-fetching)
      let users = allUsers.slice(offset, offset + limit);

      if (fields) {
        const requestedFields = fields.split(',');
        users = users.map(user => {
          const filtered = {};
          requestedFields.forEach(field => {
            if (user.hasOwnProperty(field)) {
              filtered[field] = user[field];
            }
          });
          return filtered;
        });
      }

      res.json({
        data: users,
        pagination: {
          limit,
          offset,
          total: allUsers.length,
          returned: users.length
        }
      });
    } catch (err) {
      next(err);
    }
  }
);

/**
 * Example route for POST requests with body validation
 */
app.post('/users',
  [
    body('email')
      .isEmail()
      .normalizeEmail()
      .withMessage('Invalid email address'),
    body('name')
      .trim()
      .isLength({ min: 2, max: 50 })
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name must be 2-50 characters and contain only letters, spaces, hyphens, and apostrophes'),
  ],
  validateRequest,
  (req, res) => {
    try {
      const { email, name } = req.body;
      // Process user creation...
      res.status(201).json({
        message: 'User created successfully',
        user: { id: Date.now(), name, email }
      });
    } catch (err) {
      next(err);
    }
  }
);

// ===== SERVER INITIALIZATION =====

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown handling
const gracefulShutdown = (signal) => {
  console.log(`${signal} received. Starting graceful shutdown...`);
  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  gracefulShutdown('uncaughtException');
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
});

module.exports = app;

