      message: 'User created successfully',
      data: { 
        id: newUser.id, 
        name: newUser.name, 
        email: newUser.email 
      }
    });
  })
);

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path,
    request_id: req.id
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error(`[${req.id}] Error:`, err.stack);

  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
