### Validate Optional Query Params
```javascript
query('search')
  .optional()
  .trim()
  .escape()
  .isLength({ max: 100 })
```

## Error Response Standard

```javascript
// 400 - Bad Request
{ error: 'Validation failed', details: [...] }

// 401 - Unauthorized
{ error: 'Authentication required' }

// 403 - Forbidden
{ error: 'Access denied' }

// 404 - Not Found
{ error: 'Not found', message: 'Resource not found' }

// 429 - Too Many Requests
{ error: 'Too many requests', retryAfter: '15 minutes' }

// 500 - Internal Server Error
{ error: 'Internal server error' }  // Production
{ error: 'Error name', message: 'Details', stack: '...' }  // Development
```

## Common Security Mistakes to Avoid

❌ **Don't do this:**
```javascript
app.get('/users/:id', (req, res) => {
  const id = req.params.id;  // No validation!
  db.query(`SELECT * FROM users WHERE id = ${id}`);  // SQL injection!
});
```

✅ **Do this instead:**
```javascript
app.get('/users/:id',
  param('id').isInt({ min: 1 }),
  async (req, res) => {
    const id = parseInt(req.params.id);
    const user = await db.query('SELECT * FROM users WHERE id = ?', [id]);
    res.json(user);
  }
);
```

## Health Check Best Practice
```javascript
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});
```

