const rateLimit = require('express-rate-limit');

app.use(helmet());
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests' }
}));
```

## 2. Centralized Error Handling

### Before:
```javascript
// No error handling - errors crash the app
```

### After:
```javascript
// Centralized error handler
const errorHandler = (err, req, res, next) => {
  console.error(`[${new Date().toISOString()}] Error:`, err.message);

  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: err.message || 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack }),
    requestId: req.id
  });
};

// Catch-all for undefined routes
const notFoundHandler = (req, res) => {
  res.status(404).json({
    error: 'Resource not found',
    path: req.path,
    method: req.method
  });
};
```

## 3. Input Validation

### Sanitization Function:
```javascript
const sanitizeString = (input) => {
  if (typeof input !== 'string') return input;
  return input.replace(/[<>]/g, '').trim();
};
```

### Email Validation:
```javascript
const isValidEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};
```

### ID Validation:
```javascript
const isValidId = (id) => {
  const numId = parseInt(id, 10);
  return !isNaN(numId) && numId > 0 && Number.isInteger(numId);
};
```

## 4. Route-Specific Improvements

### `/health` Endpoint
**Before:** No error handling
**After:** Wrapped in try-catch with proper error propagation

### `/users` Endpoint
**Before:** Returns all data without validation
**After:**
- Validates query parameters (limit, offset)
- Enforces limits (max 100 results)
- Sanitizes output data

### New `/users/:id` Endpoint
```javascript
app.get('/users/:id', (req, res, next) => {
  try {
    if (!isValidId(req.params.id)) {
      const error = new Error('Invalid user ID');
      error.status = 400;
      throw error;
    }
    // ... rest of handler
  } catch (error) {
    next(error);
  }
});
```

### New POST `/users` Endpoint
```javascript
app.post('/users', express.json(), (req, res, next) => {
  try {
    // Validate required fields
    if (!name || typeof name !== 'string') {
      throw new Error('Name is required');
    }

    // Validate email format
    if (!isValidEmail(email)) {
      throw new Error('Invalid email');
    }

