/**
 * Improved Express Application with Security Best Practices
 * Features: Input validation, error handling, security headers, rate limiting
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Remove X-Powered-By header
app.disable('x-powered-by');

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: {
    error: 'Too many attempts for this action, please try again later.'
  }
});

// Parse JSON with size limit to prevent payload attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ============================================
// ERROR HANDLING MIDDLEWARE
// ============================================

// 404 handler - must be after all routes
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found on this server.',
    path: req.path
  });
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error details (in production, use proper logging service)
  console.error('Error:', {
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  // Don't leak internal errors in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  const statusCode = err.statusCode || 500;
  const response = {
    error: isDevelopment ? err.name : 'Internal Server Error',
    message: isDevelopment ? err.message : 'An unexpected error occurred.',
    ...(isDevelopment && { stack: err.stack })
  };

  res.status(statusCode).json(response);
});

// ============================================
// VALIDATION MIDDLEWARE
// ============================================

/**
 * Middleware to check validation results
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation Error',
      message: 'Invalid input data',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
        value: err.value
      }))
    });
  }
  next();
};

// ============================================
// UTILITY FUNCTIONS
// ============================================

/**
 * Sanitize user object to remove sensitive fields
 */
const sanitizeUser = (user) => {
  const { id, name, email } = user;
  return { id, name, email };
};

/**
 * Validate email format
 */
const isValidEmail = (email) => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

// ============================================
// DATA LAYER (MOCK)
// ============================================

// Mock user data with proper typing
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

/**
 * Get user by ID with validation
 */
const getUserById = (id) => {
  const userId = parseInt(id, 10);
  if (isNaN(userId) || userId <= 0) {
    const error = new Error('Invalid user ID');
    error.statusCode = 400;
    throw error;
  }

  const user = users.find(u => u.id === userId);
  if (!user) {
    const error = new Error('User not found');
    error.statusCode = 404;
    throw error;
  }

  return user;
};

// ============================================
// ROUTES
// ============================================

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

/**
 * Get all users with optional filtering
 * GET /users?limit=10&offset=0&sort=name
 */
app.get('/users', [
  // Input validation with express-validator
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  query('sort')
    .optional()
    .isIn(['name', 'email', 'id'])
    .withMessage('Sort must be one of: name, email, id'),
  validateRequest
], (req, res) => {
  try {
    const { limit = 10, offset = 0, sort = 'id' } = req.query;

    // Validate and sanitize query parameters
    const sanitizedLimit = Math.min(parseInt(limit, 10), 100);
    const sanitizedOffset = Math.max(0, parseInt(offset, 10));

    // Sort users (validated sort field)
    const sortedUsers = [...users].sort((a, b) => {
      if (a[sort] < b[sort]) return -1;
      if (a[sort] > b[sort]) return 1;
      return 0;
    });

    // Paginate
    const paginatedUsers = sortedUsers
      .slice(sanitizedOffset, sanitizedOffset + sanitizedLimit)
      .map(sanitizeUser);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit: sanitizedLimit,
        offset: sanitizedOffset,
        total: users.length
      }
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get user by ID
 * GET /users/:id
 */
app.get('/users/:id', [
  param('id')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer'),
  validateRequest
], (req, res, next) => {
  try {
    const user = getUserById(req.params.id);
    res.json({ data: sanitizeUser(user) });
  } catch (error) {
    next(error);
  }
});

/**
 * Create new user (example endpoint for POST validation)
 * POST /users
 */
app.post('/users', strictLimiter, [
  body('name')
    .trim()
    .notEmpty()
    .withMessage('Name is required')
    .isLength({ min: 2, max: 100 })
    .withMessage('Name must be between 2 and 100 characters')
    .matches(/^[a-zA-Z\s\-']+$/)
    .withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .notEmpty()
    .withMessage('Email is required')
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail()
    .custom((email) => {
      if (users.some(u => u.email === email)) {
        throw new Error('Email already exists');
      }
      return true;
    }),
  validateRequest
], (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Additional validation
    if (!isValidEmail(email)) {
      const error = new Error('Invalid email format');
      error.statusCode = 400;
      throw error;
    }

    const newUser = {
      id: users.length + 1,
      name: name.trim(),
      email: email.toLowerCase().trim()
    };

    users.push(newUser);

    res.status(201).json({
      message: 'User created successfully',
      data: sanitizeUser(newUser)
    });
  } catch (error) {
    next(error);
  }
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// ============================================
// GRACEFUL SHUTDOWN
// ============================================

const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forcing shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;
module.exports.server = server;

