const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult, ExpressValidator } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Security headers for protection against common vulnerabilities
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  },
  noSniff: true,
  xssFilter: true,
  frameguard: { action: 'deny' },
}));

// Rate limiting to prevent brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
    retryAfter: 900
  },
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429).json({
      error: 'Too many requests',
      message: 'Rate limit exceeded. Please try again later.',
      retryAfter: req.rateLimit.resetTime
    });
  }
});

// Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 requests per 15 minutes
  skipSuccessfulRequests: true,
});

app.use('/api/', limiter);

// Body parsing with size limits to prevent DoS
app.use(express.json({ 
  limit: '10kb',
  strict: true
}));
app.use(express.urlencoded({ 
  extended: false, 
  limit: '10kb' 
}));

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Middleware to check validation results and respond with errors
 */
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation errors for security monitoring (without exposing sensitive data)
    console.warn(`Validation failed for ${req.method} ${req.path}:`, {
      ip: req.ip,
      userAgent: req.get('user-agent'),
      errors: errors.array().map(e => ({ 
        field: e.path, 
        message: e.msg 
      }))
    });

    return res.status(400).json({
      error: 'Validation failed',
      message: 'Invalid input data',
      details: errors.array().map(e => ({
        field: e.path,
        message: e.msg
      }))
    });
  }
  next();
};

/**
 * Sanitize user input to prevent XSS attacks
 */
const sanitizeInput = (req, res, next) => {
  const sanitize = (obj) => {
    if (typeof obj !== 'object' || obj === null) {
      return obj;
    }

    for (const key in obj) {
      if (obj.hasOwnProperty(key)) {
        if (typeof obj[key] === 'string') {
          // Remove potentially dangerous characters
          obj[key] = obj[key]
            .replace(/[<>]/g, '') // Remove < and >
            .trim();
        } else if (typeof obj[key] === 'object') {
          sanitize(obj[key]);
        }
      }
    }
    return obj;
  };

  if (req.body) sanitize(req.body);
  if (req.query) sanitize(req.query);
  if (req.params) sanitize(req.params);

  next();
};

app.use(sanitizeInput);

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * 404 Not Found handler
 */
app.use((req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found',
    path: req.path
  });
});

/**
 * Global error handler - must be last
 */
app.use((err, req, res, next) => {
  // Log the full error for debugging (in production, use proper logging service)
  console.error('Error occurred:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  const statusCode = err.statusCode || err.status || 500;
  const response = {
    error: isDevelopment ? err.name : 'Internal Server Error',
    message: isDevelopment ? err.message : 'An unexpected error occurred',
    timestamp: new Date().toISOString()
  };

  // Add request ID for tracking (generate one if not present)
  const requestId = req.id || require('crypto').randomBytes(8).toString('hex');
  response.requestId = requestId;

  res.status(statusCode).json(response);
});

/**
 * Handle uncaught exceptions
 */
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', {
    message: err.message,
    stack: err.stack,
    timestamp: new Date().toISOString()
  });
  // Perform cleanup and exit gracefully
  cleanup();
  process.exit(1);
});

/**
 * Handle unhandled promise rejections
 */
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, {
    reason: reason,
    timestamp: new Date().toISOString()
  });
  // Cleanup and exit
  cleanup();
  process.exit(1);
});

function cleanup() {
  // Add any cleanup logic here (close database connections, etc.)
  console.log('Performing cleanup...');
}

// ============================================================================
// VALIDATION SCHEMAS
// ============================================================================

const healthCheckValidation = [
  query('verbose')
    .optional()
    .isIn(['true', 'false', '1', '0'])
    .withMessage('Verbose must be a boolean value')
];

const userQueryValidation = [
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer'),
  query('email')
    .optional()
    .isEmail()
    .normalizeEmail()
    .withMessage('Email must be a valid email address'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer')
];

const userParamValidation = [
  param('userId')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer')
];

// ============================================================================
// ROUTES WITH VALIDATION
// ============================================================================

app.get('/health', healthCheckValidation, validateRequest, (req, res) => {
  const verbose = req.query.verbose === 'true' || req.query.verbose === '1';

  const response = {
    status: 'ok',
    timestamp: new Date().toISOString()
  };

  if (verbose) {
    response.uptime = process.uptime();
    response.memory = process.memoryUsage();
    response.version = process.version;
  }

  res.json(response);
});

app.get('/users', userQueryValidation, validateRequest, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply filters based on validated query parameters
    let filteredUsers = users;

    if (req.query.id) {
      filteredUsers = filteredUsers.filter(u => u.id === parseInt(req.query.id));
    }

    if (req.query.email) {
      filteredUsers = filteredUsers.filter(u => u.email === req.query.email);
    }

    // Apply pagination
    const limit = req.query.limit ? parseInt(req.query.limit) : users.length;
    const offset = req.query.offset ? parseInt(req.query.offset) : 0;

    const paginatedUsers = filteredUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        total: filteredUsers.length,
        limit: limit,
        offset: offset
      }
    });
  } catch (error) {
    // Pass any errors to the error handling middleware
    next(error);
  }
});

app.get('/users/:userId', userParamValidation, validateRequest, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const userId = parseInt(req.params.userId);
    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: `User with ID ${userId} not found`
      });
    }

    res.json(user);
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// STARTUP VALIDATION
// ============================================================================

function validateEnvironment() {
  const requiredVars = [];
  const optionalVars = [];

  // Add your required environment variables here
  // Example: requiredVars.push('DATABASE_URL', 'JWT_SECRET');

  const missing = requiredVars.filter(varName => !process.env[varName]);

  if (missing.length > 0) {
    console.error(`Missing required environment variables: ${missing.join(', ')}`);
    process.exit(1);
  }

  // Validate environment-specific settings
  if (process.env.NODE_ENV === 'production') {
    // Ensure we're not exposing debug information
    process.env.NODE_ENV = 'production';
  }

  console.log('Environment validation passed');
}

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

validateEnvironment();

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    cleanup();
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    cleanup();
    process.exit(0);
  });
});

module.exports = app;

