const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Use Helmet for security headers (CSP, XSS Protection, etc.)
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to all routes
app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 requests per 15 minutes
  skipSuccessfulRequests: true,
});

// Body size limits to prevent payload overflow attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ============================================================================
// INPUT VALIDATION HELPERS
// ============================================================================

/**
 * Sanitize and validate query parameters
 * @param {Object} query - Request query object
 * @param {Object} schema - Validation schema
 * @returns {Object} Sanitized and validated data
 */
function validateQuery(query, schema = {}) {
  const sanitized = {};
  const errors = [];

  for (const [key, rules] of Object.entries(schema)) {
    const value = query[key];

    // Check required fields
    if (rules.required && (value === undefined || value === null)) {
      errors.push(`Field '${key}' is required`);
      continue;
    }

    // Skip validation if field is optional and not provided
    if (!rules.required && (value === undefined || value === null)) {
      continue;
    }

    // Type validation
    if (rules.type && typeof value !== rules.type) {
      errors.push(`Field '${key}' must be of type ${rules.type}`);
      continue;
    }

    // String validation
    if (typeof value === 'string') {
      // Length validation
      if (rules.minLength && value.length < rules.minLength) {
        errors.push(`Field '${key}' must be at least ${rules.minLength} characters`);
        continue;
      }
      if (rules.maxLength && value.length > rules.maxLength) {
        errors.push(`Field '${key}' must be at most ${rules.maxLength} characters`);
        continue;
      }

      // Pattern validation (for email, etc.)
      if (rules.pattern && !rules.pattern.test(value)) {
        errors.push(`Field '${key}' has invalid format`);
        continue;
      }

      // Whitelist allowed characters (sanitization)
      if (rules.allowedChars) {
        const sanitizedValue = value.replace(new RegExp(`[^${rules.allowedChars}]`, 'g'), '');
        if (sanitizedValue !== value) {
          errors.push(`Field '${key}' contains invalid characters`);
          continue;
        }
        sanitized[key] = sanitizedValue;
      } else {
        // Basic sanitization: remove potentially dangerous characters
        sanitized[key] = value
          .replace(/[<>]/g, '') // Remove potential HTML tags
          .trim();
      }
    }

    // Number validation
    if (typeof value === 'number') {
      if (rules.min !== undefined && value < rules.min) {
        errors.push(`Field '${key}' must be at least ${rules.min}`);
        continue;
      }
      if (rules.max !== undefined && value > rules.max) {
        errors.push(`Field '${key}' must be at most ${rules.max}`);
        continue;
      }
      sanitized[key] = value;
    }
  }

  // Return any unknown fields (could be logged or rejected based on policy)
  const unknownFields = Object.keys(query).filter(key => !schema[key]);
  if (unknownFields.length > 0) {
    // Log unknown fields for security monitoring
    console.warn(`Unknown query parameters detected: ${unknownFields.join(', ')}`);
  }

  if (errors.length > 0) {
    const error = new Error('Validation failed');
    error.validationErrors = errors;
    throw error;
  }

  return sanitized;
}

/**
 * Validate numeric ID parameter
